package localchat;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.*;import javax.swing.*;import java.awt.*;import java.util.List;
/** Offline catalogue UI/service tests. Synthetic XLSX, no model or production documents. */
public final class CatalogueManagerTest {
 static int checks;static void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 static void xlsx(Path file,String code,String name,String unit)throws Exception{
  String[][] rows={{"Artikel","Omschrijving","Eenheid"},{code,name,unit}};StringBuilder cells=new StringBuilder();for(int i=0;i<rows.length;i++){cells.append("<row r=\"").append(i+1).append("\">");for(int j=0;j<3;j++)cells.append("<c r=\"").append((char)('A'+j)).append(i+1).append("\" t=\"inlineStr\"><is><t>").append(rows[i][j]).append("</t></is></c>");cells.append("</row>");}
  Map<String,String> contents=new LinkedHashMap<>();contents.put("xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Fixture\" sheetId=\"1\" r:id=\"s\"/></sheets></workbook>");contents.put("xl/_rels/workbook.xml.rels","<Relationships><Relationship Id=\"s\" Target=\"worksheets/sheet1.xml\"/></Relationships>");contents.put("xl/worksheets/sheet1.xml","<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>"+cells+"</sheetData></worksheet>");
  try(ZipOutputStream zip=new ZipOutputStream(Files.newOutputStream(file))){for(var entry:contents.entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));zip.write(entry.getValue().getBytes(StandardCharsets.UTF_8));zip.closeEntry();}}
 }
 static void idle(CatalogueDialog dialog)throws Exception{for(int i=0;i<400;i++){boolean[] busy={true};FeatureTest.edt(()->busy[0]=dialog.running);if(!busy[0])return;Thread.sleep(25);}throw new AssertionError("catalogue UI still busy");}
 public static void main(String[] args)throws Exception{
  Path root=Files.createTempDirectory(Files.createDirectories(Path.of(System.getProperty("localchat.home"))),"catalogues-");Path engine=Files.createDirectories(root.resolve("pdfcontrol")),original=Path.of(System.getProperty("audit.package"));for(String name:List.of("catalogue_update.py","mbs_artikelcatalogus.py"))Files.copy(original.resolve(name),engine.resolve(name));
  CatalogueStore store=new CatalogueStore(root,Path.of(System.getProperty("audit.python")),false);Path source=root.resolve("new.xlsx");xlsx(source,"MBS1","Fixture article","m");byte[] sourceBytes=Files.readAllBytes(source);
  for(String factory:CatalogueStore.FACTORIES){check(Boolean.FALSE.equals(Json.get(store.info(factory),"exists")),"each missing factory remains missing");CatalogueStore.Preview preview=store.preview(factory,source);check(preview.targetHash().equals("missing")&&!Files.exists(store.snapshot(factory)),"preview never creates active snapshot");check(CatalogueStore.number(preview.data(),"new_codes")==1,"new code counted");try{store.apply(preview,false,false);throw new AssertionError("unconfirmed import");}catch(java.io.IOException expected){check(!Files.exists(store.snapshot(factory)),"factory confirmation mandatory");}var result=store.apply(preview,true,false);check(Boolean.TRUE.equals(Json.get(result,"applied")),"first import succeeds including Lelystad");check(Json.str(Json.parse(Files.readString(store.snapshot(factory))),"factory").equals(factory),"snapshot factory isolated");check(Files.isRegularFile(Path.of(Json.str(result,"source_archive"))),"original archived");check(Arrays.equals(sourceBytes,Files.readAllBytes(source)),"original source unchanged");check(CatalogueStore.number(store.info(factory),"records")==1,"active info refreshed");}
  CatalogueStore.Preview old=store.preview("lelystad",source);xlsx(source,"MBS2","Changed article","st");try{store.apply(old,true,false);throw new AssertionError("stale source accepted");}catch(java.io.IOException expected){check(Files.readString(store.snapshot("lelystad")).contains("MBS1"),"source mutation blocks activation");}
  CatalogueStore.Preview removal=store.preview("lelystad",source);check(CatalogueStore.number(removal.data(),"absent_codes")==1,"absent codes reported");try{store.apply(removal,true,false);throw new AssertionError("unconfirmed absence");}catch(java.io.IOException expected){check(Files.readString(store.snapshot("lelystad")).contains("MBS1"),"missing-code confirmation mandatory");}store.apply(removal,true,true);check(Files.readString(store.snapshot("lelystad")).contains("MBS2"),"complete-source confirmation activates replacement");
  CatalogueStore readonly=new CatalogueStore(root,Path.of(System.getProperty("audit.python")),true);var preview=readonly.preview("soest",source);try{readonly.apply(preview,true,true);throw new AssertionError("read-only import");}catch(java.io.IOException expected){check(Files.readString(store.snapshot("soest")).contains("MBS1"),"read-only permits preview but blocks activation");}
  for(String language:I18n.CODES)for(boolean dark:List.of(false,true)){I18n.setLanguage(language);if(dark)com.formdev.flatlaf.FlatDarkLaf.setup();else com.formdev.flatlaf.FlatLightLaf.setup();FeatureTest.edt(()->{CatalogueDialog dialog=new CatalogueDialog(null,store);check(!dialog.apply.isEnabled()&&!dialog.confirmed.isSelected()&&!dialog.complete.isSelected(),"no pre-approved import");dialog.factory.setSelectedIndex(4);dialog.source.setText(source.toString());dialog.controls();check(dialog.compare.isEnabled(),"Lelystad supports file import");check(dialog.getTitle().equals(I18n.text("Cataloage fabrici")),"localized catalogue dialog");check(dialog.choose.getText().equals("\u2026"),"file chooser has a single correctly encoded ellipsis");if(language.equals("ro")){dialog.details.setText(CatalogueDialog.format(removal.data()));dialog.complete.setVisible(true);dialog.status.setText(I18n.text("Verifica diferentele si confirma fabrica inainte de activare."));dialog.setVisible(true);dialog.validate();var image=new java.awt.image.BufferedImage(dialog.getWidth(),dialog.getHeight(),java.awt.image.BufferedImage.TYPE_INT_RGB);Graphics2D g=image.createGraphics();dialog.getRootPane().printAll(g);g.dispose();javax.imageio.ImageIO.write(image,"png",root.resolve(dark?"catalogue-dark.png":"catalogue-light.png").toFile());}dialog.dispose();});}
  I18n.setLanguage("ro");CatalogueDialog[] dialog={null};xlsx(source,"MBS3","UI fixture","m");FeatureTest.edt(()->{dialog[0]=new CatalogueDialog(null,store);dialog[0].factory.setSelectedIndex(4);dialog[0].source.setText(source.toString());dialog[0].controls();dialog[0].compare.doClick();});idle(dialog[0]);FeatureTest.edt(()->{check(dialog[0].preview!=null&&dialog[0].complete.isVisible(),"real UI preview shows absent-code confirmation");dialog[0].confirmed.doClick();check(!dialog[0].apply.isEnabled(),"factory alone does not approve removal");dialog[0].complete.doClick();check(dialog[0].apply.isEnabled(),"both explicit confirmations enable import");dialog[0].apply.doClick();});idle(dialog[0]);FeatureTest.edt(()->{check(dialog[0].preview==null&&!dialog[0].apply.isEnabled(),"successful UI activation cannot repeat without preview");check(Files.readString(store.snapshot("lelystad")).contains("MBS3"),"UI sends selected file to selected factory");dialog[0].dispose();});
  System.out.println("PASS: "+checks+" catalogue manager checks; real local Python, six languages/two themes, no API");System.exit(0);
 }
}
